	/**
	 * Method to retrieve the FeatureSet via FeatureSetFetchOneSummary
	 * @param 	summary FeatureSetFetchOneSummary
	 * @return 	FeatureSetFetchOneResponse
	 */
	public FeatureSet getFeatureSet( FeatureSetFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "FeatureSetFetchOneSummary arg cannot be null" );

		FeatureSet entity = null;
		UUID id = summary.getFeatureSetId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a FeatureSet using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


